def _rust_test_body(test_reference: str) -> str | None:
    """Return one confined Rust test body for exact content-evidence checks."""
    test_path, separator, test_name = test_reference.partition("::")
    if not separator or not test_name:
        return None
    confined_source = test_feature_traceability._read_confined_test_source(test_path)
    if confined_source is None or confined_source[0].suffix != ".rs":
        return None
    _, source = confined_source
    source_without_comments_or_literals = test_feature_traceability._strip_rust_comments_and_literals(source)
    if source_without_comments_or_literals is None:
        return None
    declaration = re.compile(
        rf"\bfn\s+{re.escape(test_name)}\s*\([^)]*\)\s*\{{"
    )
    match = declaration.search(source_without_comments_or_literals)
    if match is None:
        return None
    opening_brace = match.end() - 1
    depth = 0
    for index in range(opening_brace, len(source_without_comments_or_literals)):
        if source_without_comments_or_literals[index] == "{":
            depth += 1
        elif source_without_comments_or_literals[index] == "}":
            depth -= 1
            if depth == 0:
                return source[opening_brace + 1:index]
    return None


def _selected_profile_source_scope(
    catalog: dict[str, Any], target_manifest: dict[str, Any]
) -> tuple[set[str], set[tuple[str, str]], set[str] | None]:
    """Resolve selected profile clauses, source sections, and explicit requirement IDs."""
    profiles = {profile["profile_id"]: profile for profile in catalog["profiles"]}
    selected_profiles = [profiles[profile_id] for profile_id in target_manifest["profile_ids"]]
    selected_clause_ids = {
        clause_id
        for profile in selected_profiles
        for clause_id in profile["source_clause_ids"]
    }
    clauses_by_id = {clause["clause_id"]: clause for clause in catalog["source_clauses"]}
    selected_source_sections = {
        (clauses_by_id[clause_id]["source_id"], clauses_by_id[clause_id]["section"])
        for clause_id in selected_clause_ids
    }
    selected_requirement_ids = None
    if all("requirement_ids" in profile for profile in selected_profiles):
        selected_requirement_ids = {
            requirement_id
            for profile in selected_profiles
            for requirement_id in profile["requirement_ids"]
        }
    return selected_clause_ids, selected_source_sections, selected_requirement_ids


def _has_reviewed_client_actor(record: dict[str, Any]) -> bool:
    """Return whether the source or an explicit project interpretation assigns client scope."""
    if record.get("project_actor_interpretation") == "client":
        return True
    actor = record.get("actor")
    if not isinstance(actor, str):
        return False
    normalized_actor = actor.strip().casefold()
    # Source reviews may elaborate the actor; only its leading role token is authoritative.
    return normalized_actor.partition(" ")[0] == "client"


def _reviewed_profile_optional_capabilities(
    oracle: dict[str, Any],
    selected_clause_ids: set[str],
    selected_source_sections: set[tuple[str, str]],
    selected_requirement_ids: set[str] | None = None,
) -> tuple[set[str], list[str]]:
    """Collect source-reviewed MAY/OPTIONAL candidates in the selected profile closure."""
    capabilities: set[str] = set()
    gaps: list[str] = []
    explicit_source_gaps = {
        gap["gap_id"]: gap for gap in oracle.get("source_only_requirement_gaps", [])
    }
    for review in oracle["source_requirement_reviews"]:
        if review["source_clause_id"] not in selected_clause_ids:
            continue
        for obligation in review["source_obligations"]:
            if (
                obligation["source_keyword"] not in {"MAY", "OPTIONAL"}
                or obligation["scope_disposition"] not in {"client_1_0", "profile_conditional"}
            ):
                continue
            candidate_id = obligation["candidate_requirement_id"]
            if (
                obligation["scope_disposition"] == "profile_conditional"
                and selected_requirement_ids is not None
                and candidate_id not in selected_requirement_ids
            ):
                continue
            if candidate_id is None:
                gap_ref = obligation.get("source_gap_id")
                if gap_ref not in explicit_source_gaps:
                    gaps.append(
                        f"{review['source_clause_id']} source capability has no stable candidate ID or explicit gap record"
                    )
                else:
                    gaps.append(
                        f"{gap_ref}: in-scope {obligation['source_keyword']} capability has no stable candidate ID"
                    )
                continue
            if obligation["scope_disposition"] == "profile_conditional":
                condition = obligation.get("condition")
                if not isinstance(condition, str) or not condition.strip():
                    gaps.append(
                        f"{candidate_id}: conditional MAY/OPTIONAL capability has no source condition"
                    )
                if not _has_reviewed_client_actor(obligation):
                    gaps.append(
                        f"{candidate_id}: conditional MAY/OPTIONAL capability has no reviewed client actor"
                    )
            capabilities.add(candidate_id)

    for gap in oracle.get("source_only_requirement_gaps", []):
        source_clause_id = gap.get("source_clause_id")
        if source_clause_id is not None:
            is_selected = source_clause_id in selected_clause_ids
        else:
            source_id = gap.get("source_id")
            source_section = gap.get("source_section")
            is_selected = bool(
                source_id
                and source_section
                and any(
                    selected_source_id == source_id
                    and (
                        source_section == selected_section
                        or source_section.startswith(f"{selected_section}.")
                    )
                    for selected_source_id, selected_section in selected_source_sections
                )
            )
        if not is_selected:
            continue
        if (
            set(gap["source_keywords"]) & {"MAY", "OPTIONAL"}
            and gap["scope_disposition"] in {"client_1_0", "profile_conditional"}
        ):
            candidate_id = gap["candidate_requirement_id"]
            if (
                gap["scope_disposition"] == "profile_conditional"
                and selected_requirement_ids is not None
                and candidate_id not in selected_requirement_ids
            ):
                continue
            if candidate_id is None:
                gaps.append(
                    f"{gap['gap_id']}: in-scope optional capability has no stable candidate ID "
                    f"(proposed {gap['proposed_requirement_id']})"
                )
                continue
            if gap["scope_disposition"] == "profile_conditional":
                condition = gap.get("condition")
                if not isinstance(condition, str) or not condition.strip():
                    gaps.append(
                        f"{candidate_id}: conditional MAY/OPTIONAL source gap has no resolved condition"
                    )
                if not _has_reviewed_client_actor(gap):
                    gaps.append(
                        f"{candidate_id}: conditional MAY/OPTIONAL source gap has no reviewed client actor"
                    )
            capabilities.add(candidate_id)
    return capabilities, gaps


def _reviewed_profile_conditional_capability_sources(
    oracle: dict[str, Any],
    selected_clause_ids: set[str],
    selected_source_sections: set[tuple[str, str]],
    selected_requirement_ids: set[str] | None = None,
) -> dict[str, set[str]]:
    """Return selected source clauses that conditionally authorize optional capabilities."""
    conditional_sources: dict[str, set[str]] = {}
    for review in oracle["source_requirement_reviews"]:
        source_clause_id = review["source_clause_id"]
        if source_clause_id not in selected_clause_ids:
            continue
        for obligation in review["source_obligations"]:
            candidate_id = obligation.get("candidate_requirement_id")
            if (
                obligation.get("source_keyword") in {"MAY", "OPTIONAL"}
                and obligation.get("scope_disposition") == "profile_conditional"
                and isinstance(candidate_id, str)
                and (
                    selected_requirement_ids is None
                    or candidate_id in selected_requirement_ids
                )
            ):
                conditional_sources.setdefault(candidate_id, set()).add(source_clause_id)

    for gap in oracle.get("source_only_requirement_gaps", []):
        source_clause_id = gap.get("source_clause_id")
        if source_clause_id is not None:
            is_selected = source_clause_id in selected_clause_ids
        else:
            source_id = gap.get("source_id")
            source_section = gap.get("source_section")
            is_selected = bool(
                source_id
                and source_section
                and any(
                    selected_source_id == source_id
                    and (
                        source_section == selected_section
                        or source_section.startswith(f"{selected_section}.")
                    )
                    for selected_source_id, selected_section in selected_source_sections
                )
            )
        candidate_id = gap.get("candidate_requirement_id")
        if (
            is_selected
            and gap.get("scope_disposition") == "profile_conditional"
            and set(gap.get("source_keywords", [])) & {"MAY", "OPTIONAL"}
            and _has_reviewed_client_actor(gap)
            and isinstance(source_clause_id, str)
            and isinstance(candidate_id, str)
            and (
                selected_requirement_ids is None
                or candidate_id in selected_requirement_ids
            )
        ):
            conditional_sources.setdefault(candidate_id, set()).add(source_clause_id)
    return conditional_sources


def _has_linked_typed_optional_capability_rule(
    requirement: dict[str, Any],
    expected_source_clause_ids: set[str],
    typed_rule_mappings: list[dict[str, Any]],
    usable_positive_tests: list[str],
) -> bool:
    """Require a typed optional rule and its exact linked positive test."""
    requirement_id = requirement["requirement_id"]
    requirement_source_clause_ids = set(requirement.get("source_clause_ids", []))
    requirement_test_refs = set(requirement.get("verification_refs", []))
    return any(
        mapping.get("requirement_id") == requirement_id
        and mapping.get("source_clause_id") in expected_source_clause_ids
        and mapping.get("source_clause_id") in requirement_source_clause_ids
        and mapping.get("verification_category") == "OptionalCapability"
        and mapping.get("evaluator_present") is True
        and mapping.get("test_kind") == "OptionalCapabilityUsable"
        and mapping.get("test_id") in requirement_test_refs
        and mapping.get("test_id") in usable_positive_tests
        for mapping in typed_rule_mappings
    )


def _has_profile_rule_implementation(resolvable_implementation_refs: list[str]) -> bool:
    """Check that a runtime profile evaluator is among the resolvable implementations."""
    return any(
        reference.partition("::")[0] == PROFILE_RULE_SOURCE
        for reference in resolvable_implementation_refs
    )


def _has_usable_conditional_client_exchange_evidence(
    requirement: dict[str, Any],
    conditional_source_clause_ids: set[str],
    typed_rule_mappings: list[dict[str, Any]],
    resolvable_implementation_refs: list[str],
    usable_positive_tests: list[str],
) -> bool:
    """Require an exact typed source rule and named test for conditional client capability evidence."""
    condition = requirement.get("condition")
    has_source_condition = isinstance(condition, str) and bool(condition.strip())
    has_typed_rule_implementation = _has_profile_rule_implementation(
        resolvable_implementation_refs
    )
    has_linked_typed_positive_rule = _has_linked_typed_optional_capability_rule(
        requirement,
        conditional_source_clause_ids,
        typed_rule_mappings,
        usable_positive_tests,
    )
    return (
        requirement.get("scope_state") == "profile_conditional"
        and requirement.get("status") == "scoped_verified"
        and requirement.get("role") == "client"
        and requirement.get("direction") in {"client_to_server", "server_to_client", "both"}
        and has_source_condition
        and bool(resolvable_implementation_refs)
        and has_typed_rule_implementation
        and bool(usable_positive_tests)
        and has_linked_typed_positive_rule
    )


def _has_usable_profile_optional_evidence(
    requirement: dict[str, Any],
    conditional_source_clause_ids: set[str],
    typed_rule_mappings: list[dict[str, Any]],
    resolvable_implementation_refs: list[str],
    usable_positive_tests: list[str],
) -> bool:
    """Apply the profile-specific evidence gate without inferring source direction."""
    if not usable_positive_tests:
        return False
    if requirement["scope_state"] == "profile_conditional":
        return _has_usable_conditional_client_exchange_evidence(
            requirement,
            conditional_source_clause_ids,
            typed_rule_mappings,
            resolvable_implementation_refs,
            usable_positive_tests,
        )

    direction = requirement["direction"]
    condition = requirement.get("condition")
    has_unambiguous_source_condition = isinstance(condition, str) and bool(condition.strip())
    has_profile_rule_implementation = _has_profile_rule_implementation(
        resolvable_implementation_refs
    )
    has_linked_typed_positive_rule = _has_linked_typed_optional_capability_rule(
        requirement,
        set(requirement.get("source_clause_ids", [])),
        typed_rule_mappings,
        usable_positive_tests,
    )
    unclear_direction_has_typed_evidence = (
        direction != "unclear"
        or (
            has_unambiguous_source_condition
            and has_profile_rule_implementation
            and has_linked_typed_positive_rule
        )
    )
    response_direction_has_typed_evidence = (
        direction not in {"server_to_client", "both"}
        or has_linked_typed_positive_rule
    )
    scoped_client_exchange_evidence = (
        requirement["status"] == "scoped_verified"
        and requirement["role"] == "client"
        and direction in {"client_to_server", "server_to_client", "both", "unclear"}
        and requirement["scope_state"] == "client_1_0"
        and bool(resolvable_implementation_refs)
        and unclear_direction_has_typed_evidence
        and response_direction_has_typed_evidence
    )
    return requirement["status"] == "verified" or scoped_client_exchange_evidence


def source_table_contracts_for_gap(
    contracts: list[dict[str, Any]], gap_id: str
) -> list[dict[str, Any]]:
    """Return every contract for a source gap so callers can assert cardinality."""
    return [contract for contract in contracts if contract.get("gap_id") == gap_id]


class _CandidateTextParser(_CandidateParser):
    """Retain each pinned candidate's normalized text for fixture provenance checks."""

    def _finish_candidate(self, candidate: dict[str, object]) -> None:
        text = "".join(candidate["text"])
        previous_count = len(self.candidates)
        super()._finish_candidate(candidate)
        if len(self.candidates) > previous_count:
            self.candidates[-1]["source_text"] = " ".join(text.split())


def audit_document_with_text(raw: bytes, source_id: str) -> list[dict[str, object]]:
    """Return source candidates with normalized text for exact locator-to-atom checks."""
    parser = _CandidateTextParser(source_id)
    parser.feed(_decode_document(raw))
    parser.close()
    return parser.candidates


class _PlainTextParser(HTMLParser):
    """Flatten an exact pinned HTML line span for source-gap provenance checks."""

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        self.parts.append(data)

    def normalized_text(self) -> str:
        return " ".join("".join(self.parts).split())


_ORPHANED_HTML_ATTRIBUTE_PREFIX = re.compile(
    r"^(?:style|class)\s*=\s*(['\"]).*?\1>",
    re.IGNORECASE,
)


def pinned_source_excerpt(relative_path: str, line_range: list[int]) -> str:
    """Return normalized text from a one-based pinned HTML line range."""
    lines = _decode_document((ROOT / relative_path).read_bytes()).splitlines()
    parser = _PlainTextParser()
    parser.feed("\n".join(lines[line_range[0] - 1 : line_range[1]]))
    parser.close()
    text = parser.normalized_text()
    # Table-row spans can begin in the middle of an HTML attribute when the
    # source wraps a cell across physical lines. Drop that orphaned markup.
    return _ORPHANED_HTML_ATTRIBUTE_PREFIX.sub("", text).strip()


