        self.assertEqual(
            set(discrepancy["affected_profile_ids"]),
            {"KMIPKIT-PROFILE-JSON-CLIENT", "KMIPKIT-PROFILE-JSON-SERVER"},
        )

        json_sample = next(
            row for row in catalog["test_cases"] if row["test_id"] == "KMIPKIT-TEST-PROF-5-5-4-1"
        )
