    def test_checked_in_catalog_reconciles_profile_and_official_test_evidence(self) -> None:
        catalog_path = ROOT / "specification" / "catalog" / "kmip-2.1.json"
        raw = catalog_path.read_bytes()

        validated = validate_catalog(raw, ROOT, require_complete=True)

        self.assertGreater(validated["record_count"], 0)
        document = json.loads(raw)
        profiles = document["profiles"]
        self.assertEqual(len(profiles), 35)
        self.assertTrue({"client", "server"}.issubset({profile["role"] for profile in profiles}))
        baseline_state = next(
            profile["claim_state"]
            for profile in profiles
            if profile["profile_id"] == "KMIPKIT-PROFILE-BASELINE-CLIENT"
        )
        self.assertEqual("evidence_incomplete", baseline_state)
        self.assertTrue(all(
            profile["claim_state"] == "not_claimed"
            for profile in profiles
            if profile["profile_id"] != "KMIPKIT-PROFILE-BASELINE-CLIENT"
        ))
        self.assertTrue(all(profile["source_refs"] for profile in profiles))
        self.assertTrue(all(profile["source_clause_ids"] for profile in profiles))
        self.assertTrue(all(profile["requirement_ids"] for profile in profiles))
        self.assertTrue(all(profile["test_case_ids"] for profile in profiles))
        self.assertTrue(all(isinstance(profile["transport_requirements"], list) for profile in profiles))
        self.assertTrue(all(isinstance(profile["encoding_requirements"], list) for profile in profiles))
        self.assertTrue(all(profile["applicability"] in {
            "client_1_0", "client_1_1", "server_only", "conditional", "out_of_scope"
        } for profile in profiles))
        conformance_sections = {
            reference["section"]
            for profile in profiles
            for reference in profile["source_refs"]
            if reference["source_id"] == "KMIPKIT-SRC-profiles"
            and reference["section"].startswith("6.")
        }
        self.assertEqual(conformance_sections, {f"6.{section}" for section in range(1, 36)})

    def test_baseline_fixtures_are_pinned_but_do_not_complete_conformance_evidence(self) -> None:
        catalog = json.loads((ROOT / "specification/catalog/kmip-2.1.json").read_text(encoding="utf-8"))
        target_manifest = json.loads(
            (ROOT / "specification/catalog/profile-targets.json").read_text(encoding="utf-8")
        )
        baseline = next(
            profile
            for profile in catalog["profiles"]
            if profile["profile_id"] == "KMIPKIT-PROFILE-BASELINE-CLIENT"
        )
        required_tests = [
            test_case
            for test_case in catalog["test_cases"]
            if test_case["test_id"] in baseline["test_case_ids"]
            and test_case["mandatory_status"] == "mandatory"
        ]

        self.assertIn(baseline["profile_id"], target_manifest["profile_ids"])
        self.assertEqual(16, len(required_tests))
        source_index = (ROOT / "specification/oasis/kmip-2.1/SOURCES.md").read_text(encoding="utf-8")
        for test in required_tests:
            expected_path = f"specification/oasis/kmip-2.1/fixtures/{test['official_case_id']}.xml"
            self.assertEqual("available", test["fixture_availability"])
            self.assertEqual(expected_path, test["fixture_path"])
            self.assertEqual(
                f"test-cases/kmip-v2.1/mandatory/{test['official_case_id']}.xml",
                test["raw_href"],
            )
            fixture = ROOT / expected_path
            source_row = next(
                line for line in source_index.splitlines()
                if f"`fixtures/{test['official_case_id']}.xml`" in line
            )
            expected_sha256 = re.search(r"`([0-9a-f]{64})`", source_row)
            self.assertIsNotNone(expected_sha256)
            self.assertEqual(expected_sha256.group(1), hashlib.sha256(fixture.read_bytes()).hexdigest())
            root = ElementTree.parse(fixture).getroot()
            self.assertEqual("KMIP", root.tag)
            self.assertEqual(
                len(root.findall("RequestMessage")),
                len(root.findall("ResponseMessage")),
            )
            self.assertGreater(len(root.findall("RequestMessage")), 0)
            interop_ids = {
                element.attrib.get("value")
                for element in root.iter("InteropIdentifier")
            }
            if test["official_case_id"].startswith("BL-"):
                self.assertEqual({test["official_case_id"]}, interop_ids)
            else:
                self.assertEqual(set(), interop_ids)
        self.assertEqual("evidence_incomplete", baseline["claim_state"])

