                ("PKCS#11 Interface", "No", "client", [31184, 31202]),
                ("PKCS#11 Function", "Yes", "client", [31203, 31221]),
                ("Correlation Value", "No", "client", [31222, 31240]),
                ("PKCS#11 Input Parameters", "No", "client", [31241, 31259]),
