    def test_reviewed_source_requirement_mappings_match_pinned_locators_and_scope(self) -> None:
        """Reviewed source atoms, stable labels, and client dispositions agree with pinned HTML."""
        oracle = json.loads(
            (ROOT / "tools" / "normative_catalog" / "tests" / "fixtures" / "profile-closure-v2.1.json").read_text(encoding="utf-8")
        )
        catalog = json.loads(
            (ROOT / "specification" / "catalog" / "kmip-2.1.json").read_text(encoding="utf-8")
        )
        candidate_requirements = {
            row["requirement_id"]: row for row in catalog["requirements"]
        }
        client_profiles = [row for row in catalog["profiles"] if row["role"] == "client"]
        source_clauses = {row["clause_id"]: row for row in catalog["source_clauses"]}
        normative_inclusions = {
            row["inclusion_id"]: row for row in catalog["normative_inclusions"]
        }
        profiles_by_id = {row["profile_id"]: row for row in client_profiles}
        parsed_sources: dict[str, dict[str, dict[str, object]]] = {}
        violations: list[str] = []
        explicit_gaps = {
            gap["gap_id"]: gap for gap in oracle.get("source_only_requirement_gaps", [])
        }

        for review in oracle["source_requirement_reviews"]:
            source_id = review["source_id"]
            if source_id not in parsed_sources:
                raw_source = (ROOT / review["source_path"]).read_bytes()
                parsed_sources[source_id] = {
                    row["clause_id"]: row for row in audit_document_with_text(raw_source, source_id)
                }
            pinned_clause = parsed_sources[source_id].get(review["source_clause_id"])
            if pinned_clause is None:
                violations.append(f"unresolved reviewed source clause {review['source_clause_id']}")
                continue
            if pinned_clause["section"] != review["source_section"]:
                violations.append(f"{review['source_clause_id']} section differs from its pinned locator")
            if pinned_clause["locator"] != review["source_locator"]:
                violations.append(f"{review['source_clause_id']} locator differs from its pinned source")

            reviewed_client_ids = set()
            source_excerpt = pinned_clause["source_text"]
            if review["source_clause_id"] == "KMIPKIT-CLAUSE-SPEC-6.1.53.1-001":
                source_excerpt = review["source_context"]
            normalized_source_text = str(source_excerpt)
            previous_source_offset = -1
            for obligation in review["source_obligations"]:
                normalized_obligation = " ".join(obligation["source_text"].split())
                source_offset = normalized_source_text.find(
                    normalized_obligation, max(previous_source_offset, 0)
                )
                if source_offset < 0:
                    violations.append(
                        f"{review['source_clause_id']} source atom {obligation['source_order']} is not an ordered excerpt of its pinned locator"
                    )
                else:
                    previous_source_offset = source_offset
                source_keyword = obligation["source_keyword"]
                keyword_token = source_keyword.split(" (", 1)[0]
                if keyword_token in catalog_validate.KEYWORD_STRENGTH and not re.search(
                    rf"\b{re.escape(keyword_token)}\b",
                    normalized_obligation,
                ):
                    violations.append(
                        f"{review['source_clause_id']} source atom {obligation['source_order']} "
                        f"does not contain its declared keyword {keyword_token}"
                    )
                candidate_id = obligation["candidate_requirement_id"]
                if candidate_id is None:
                    if obligation["scope_disposition"] in {"client_1_0", "profile_conditional"}:
                        gap_ref = obligation.get("source_gap_id")
                        if gap_ref not in explicit_gaps:
                            violations.append(
                                f"{review['source_clause_id']} in-scope source atom "
                                f"{obligation['source_order']} has no stable requirement ID or explicit gap"
                            )
                        elif explicit_gaps[gap_ref].get("candidate_requirement_id") is None:
                            violations.append(
                                f"{gap_ref} is a source-identified in-scope atom without a stable requirement ID"
                            )
                    continue
                reviewed_scope = obligation["scope_disposition"]
                actor_is_client_attributed = (
                    obligation["actor"] != "unresolved"
                    or obligation.get("project_actor_interpretation") == "client"
                )
                if (
                    actor_is_client_attributed
                    and (
                        reviewed_scope in {"client_1_0", "profile_conditional"}
                        or reviewed_scope == "client_1_0 + server_only (split/shared)"
                    )
                ):
                    reviewed_client_ids.add(candidate_id)
                candidate = candidate_requirements.get(candidate_id)
                if candidate is None:
                    violations.append(f"candidate stable label is unresolved: {candidate_id}")
                else:
                    table_gap_id = candidate.get("source_gap_id")
                    if table_gap_id is not None:
                        table_gap = explicit_gaps.get(table_gap_id)
                        if (
                            table_gap is None
                            or table_gap.get("candidate_requirement_id") != candidate_id
                            or table_gap.get("source_locator") != candidate.get("source_locator")
                            or table_gap.get("source_force") != candidate.get("source_force")
                        ):
                            violations.append(f"{candidate_id} does not map to its exact reviewed table-row gap")
                    elif review["source_clause_id"] not in candidate["source_clause_ids"]:
                        violations.append(f"{candidate_id} does not map to its reviewed source clause")
                    candidate_source_scopes = {
                        {"unresolved": "unclear", "client_1_0 + server_only (split/shared)": "mixed"}.get(
                            other["scope_disposition"], other["scope_disposition"]
                        )
                        for other in review["source_obligations"]
                        if other.get("candidate_requirement_id") == candidate_id
                    }
                    if {"client_1_0", "server_only"}.issubset(candidate_source_scopes):
                        candidate_source_scopes.add("mixed")
                    normalized_scope = {
                        "unresolved": "unclear",
                        "client_1_0 + server_only (split/shared)": "mixed",
                    }.get(reviewed_scope, reviewed_scope)
                    if candidate["scope_state"] not in candidate_source_scopes or normalized_scope not in candidate_source_scopes:
                        violations.append(
                            f"{candidate_id} catalog scope differs from reviewed source disposition "
                            f"{reviewed_scope}"
                        )
                if candidate.get("source_gap_id") is None and obligation["source_keyword"] not in pinned_clause["source_keywords"]:
                    violations.append(
                        f"{review['source_clause_id']} source atom {obligation['source_order']} keyword is absent from the pinned locator"
                    )

            for gap in oracle.get("source_only_requirement_gaps", []):
                reused_id = gap.get("reused_requirement_id")
                review_locator = review.get("source_locator") or {}
                gap_locator = gap.get("source_locator") or {}
                reviewed_login_logout_request_row = (
                    source_id == "KMIPKIT-SRC-spec"
                    and review["source_section"] in {"6.1.30", "6.1.31"}
                    and review_locator.get("ordinal") == 1
                    and gap_locator.get("table") == "request_payload"
                )
                if (
                    reused_id is None
                    or gap["source_id"] != source_id
                    or gap["source_section"] != review["source_section"]
                    or (
                        gap["html_line_range"] != review["html_line_range"]
                        and not reviewed_login_logout_request_row
                    )
                ):
                    continue
                candidate = candidate_requirements.get(reused_id)
                if gap.get("reuse_kind") == "contextual_capability":
                    if candidate is None:
                        violations.append(f"contextual source label is unresolved: {reused_id}")
                        continue
                    if reused_id != "KMIPKIT-REQ-SPEC-6.1-004":
                        violations.append(f"{gap['gap_id']} uses an unapproved contextual capability label")
                    if candidate.get("role") != "client" or candidate.get("source_keyword") != "MAY":
                        violations.append(f"{gap['gap_id']} contextual label is not a client MAY capability")
                    if "KMIPKIT-CLAUSE-SPEC-6.1-004" not in candidate.get("source_clause_ids", []):
                        violations.append(f"{gap['gap_id']} contextual label lost its generic source owner")
                    if review["source_clause_id"] in candidate.get("source_clause_ids", []):
                        violations.append(f"{gap['gap_id']} contextual reuse incorrectly maps the Fresh exception clause")
                    if gap["candidate_requirement_id"] != reused_id:
                        violations.append(f"{gap['gap_id']} candidate and contextual reuse IDs differ")
                    if gap["scope_disposition"] != "client_1_0":
                        violations.append(f"{gap['gap_id']} contextual capability is outside client 1.0 scope")
                    if reused_id in review["expected_client_requirement_ids"]:
                        violations.append(f"{gap['gap_id']} contextual reuse became a formal §4.24 requirement")
                    if "contextually reuse" not in gap.get("review_note", "").lower():
                        violations.append(f"{gap['gap_id']} does not document contextual reuse")
                    if " ".join(gap["source_excerpt"].split()) != " ".join(review["source_excerpt"].split()):
                        violations.append(f"{gap['gap_id']} does not identify the exact reviewed source locator")
                    continue
                if candidate is None:
                    violations.append(f"reused source label is unresolved: {reused_id}")
                    continue
                table_gap_id = candidate.get("source_gap_id")
                if table_gap_id is not None:
                    if (
                        table_gap_id != gap["gap_id"]
                        or candidate.get("source_locator") != gap.get("source_locator")
                        or candidate.get("source_force") != gap.get("source_force")
                    ):
                        violations.append(f"{gap['gap_id']} reuse {reused_id} does not map to the exact table-row gap")
                    if gap["candidate_requirement_id"] != reused_id:
                        violations.append(f"{gap['gap_id']} candidate and reused IDs differ")
                    if gap["scope_disposition"] not in {"client_1_0", "profile_conditional"}:
                        violations.append(f"{gap['gap_id']} reuses a label outside client scope")
                    if " ".join(gap["source_excerpt"].split()) != " ".join(pinned_source_excerpt(gap["source_path"], gap["html_line_range"]).split()):
                        violations.append(f"{gap['gap_id']} does not identify the exact pinned table row")
                    if reused_id not in review["expected_client_requirement_ids"]:
                        violations.append(
                            f"{gap['gap_id']} reuse {reused_id} is absent from reviewed expected client membership"
                        )
                    reviewed_client_ids.add(reused_id)
                    continue
                if review["source_clause_id"] not in candidate["source_clause_ids"]:
                    violations.append(
                        f"{gap['gap_id']} reuse {reused_id} does not map to the reviewed source clause"
                    )
                if gap["candidate_requirement_id"] != reused_id:
                    violations.append(f"{gap['gap_id']} candidate and reused IDs differ")
                if gap["scope_disposition"] not in {"client_1_0", "profile_conditional"}:
                    violations.append(f"{gap['gap_id']} reuses a label outside client scope")
                if reused_id not in review["expected_client_requirement_ids"]:
                    violations.append(
                        f"{gap['gap_id']} reuse {reused_id} is absent from reviewed expected client membership"
                    )
                if " ".join(gap["source_excerpt"].split()) != " ".join(review["source_excerpt"].split()):
                    violations.append(f"{gap['gap_id']} does not identify the exact reviewed source locator")
                reviewed_client_ids.add(reused_id)

            if set(review["expected_client_requirement_ids"]) != reviewed_client_ids:
                violations.append(
                    f"{review['source_clause_id']} expected client IDs differ from its reviewed source dispositions"
                )
            rejected_ids = {
                candidate["requirement_id"]
                for candidate in review["rejected_candidate_mappings"]
            }
            reused_body_row_ids = {
                candidate["requirement_id"]
                for candidate in review["rejected_candidate_mappings"]
                if candidate["expected_disposition"] in TABLE_HEADER_REJECTION_DISPOSITIONS
                and candidate["requirement_id"] in candidate_requirements
                and _is_required_table_body_requirement(candidate_requirements[candidate["requirement_id"]])
            }
            expected_ids = set(review["expected_client_requirement_ids"])
            if expected_ids & rejected_ids:
                violations.append(f"{review['source_clause_id']} has IDs both accepted and source-rejected")
            for profile in client_profiles:
                unexpected = sorted((rejected_ids - reused_body_row_ids) & set(profile["requirement_ids"]))
                if unexpected:
                    violations.append(f"{profile['profile_id']} includes source-rejected candidates {unexpected}")
                applies_to = review.get("applies_to", "all_client_profiles")
                applies_to_profile = (
                    applies_to == "all_client_profiles"
                    or applies_to == profile["profile_id"]
                    or (isinstance(applies_to, list) and profile["profile_id"] in applies_to)
                )
                if applies_to_profile:
                    applicable_ids = {
                        requirement_id
                        for requirement_id in expected_ids
                        if (requirement := candidate_requirements.get(requirement_id)) is not None
                        and (
                            requirement["scope_state"] != "profile_conditional"
                            or profile["profile_id"] in requirement["profile_ids"]
                        )
                    }
                    missing = sorted(applicable_ids - set(profile["requirement_ids"]))
                    if missing:
                        violations.append(f"{profile['profile_id']} omits reviewed requirements {missing}")

        for gap in oracle.get("source_only_requirement_gaps", []):
            if gap["scope_disposition"] in {"client_1_0", "profile_conditional"}:
                if gap["candidate_requirement_id"] is None:
                    resolution = gap.get("source_resolution")
                    resolution_kind = resolution.get("kind") if isinstance(resolution, dict) else None
                    if resolution_kind not in {
                        "procedure_context",
                        "generic_parameter_context",
                        "attribute_policy_mapping",
                        "normative_inclusion",
                        "optional_client_capability_context",
                        "operation_table_precedence",
                    }:
                        violations.append(
                            f"{gap['gap_id']} is in-scope without a requirement ID or reviewed source disposition "
                            f"(proposal={gap['proposed_requirement_id']})"
                        )
                    elif resolution_kind == "attribute_policy_mapping":
                        element = next(
                            (
                                record
                                for record in catalog["elements"]
                                if record.get("element_id") == resolution.get("element_id")
                            ),
                            None,
                        )
                        if element is None or element.get(resolution.get("catalog_property")) != "No":
                            violations.append(f"{gap['gap_id']} does not resolve to a read-only client attribute policy")
                    elif resolution_kind == "normative_inclusion":
                        source_clause = source_clauses.get(resolution.get("source_clause_id"))
                        inclusion = normative_inclusions.get(resolution.get("inclusion_id"))
                        profile = profiles_by_id.get(resolution.get("profile_id"))
                        if (
                            source_clause is None
                            or inclusion is None
                            or profile is None
                            or source_clause.get("source_id") != gap["source_id"]
                            or source_clause.get("section") != gap["source_section"]
                            or source_clause.get("scope_state") != gap["scope_disposition"]
                            or source_clause.get("role") != "client"
                            or source_clause["clause_id"] not in profile["direct_source_clause_ids"]
                            or inclusion.get("source_clause_id") != source_clause["clause_id"]
                            or inclusion.get("included_source_id") != resolution.get("included_source_id")
                            or inclusion.get("included_section") != resolution.get("included_section")
                            or inclusion.get("included_source_id") != gap["source_id"]
                        ):
                            violations.append(
                                f"{gap['gap_id']} does not resolve to its exact client profile inclusion edge"
                            )
                    elif resolution_kind == "optional_client_capability_context":
                        if (
                            gap["gap_id"] != "KMIPKIT-SOURCE-GAP-SPEC-6.1-MULTIPART-OPTIONAL-PREFACE"
                            or resolution.get("related_requirement_ids") != []
                            or gap.get("proposed_requirement_id") is not None
                            or "optionally" not in gap["source_excerpt"].casefold()
                            or "OPTIONAL" in gap["source_excerpt"]
                        ):
                            violations.append(
                                f"{gap['gap_id']} does not preserve the optional preface as context without a formal requirement ID"
                            )
                    elif resolution_kind == "operation_table_precedence":
                        if (
                            gap["gap_id"] != "KMIPKIT-SOURCE-GAP-SPEC-6.1-PARAGRAPH-009"
                            or resolution.get("decision_id") != "KMIPKIT-DEC-015"
                            or resolution.get("related_requirement_ids") != []
                            or gap.get("proposed_requirement_id") is not None
                            or "no standalone paragraph-009 requirement ID" not in resolution.get("review_note", "")
                        ):
                            violations.append(
                                f"{gap['gap_id']} does not preserve the approved operation-table reconciliation without a new requirement ID"
                            )

        self.assertEqual(violations, [], "pinned-source requirement review mismatches: " + "; ".join(violations))

    def test_three_specification_client_atoms_have_stable_catalog_mappings(self) -> None:
        """Shared source clauses retain separate, exact client requirement mappings."""
        catalog = json.loads(
            (ROOT / "specification" / "catalog" / "kmip-2.1.json").read_text(encoding="utf-8")
        )
        oracle = json.loads(
            (ROOT / "tools" / "normative_catalog" / "tests" / "fixtures" / "profile-closure-v2.1.json").read_text(encoding="utf-8")
        )
        expected = (
            (
                "KMIPKIT-SOURCE-GAP-SPEC-4.39-LOWERCASE-FRIENDLY-NAME",
                "KMIPKIT-CLAUSE-SPEC-4.39-002",
                "KMIPKIT-REQ-SPEC-4.39-002-001",
                3,
                "SHOULD",
                "client_to_server",
                [17251, 17256],
                "client and server",
                "client_1_0",
            ),
            (
                "KMIPKIT-SOURCE-GAP-SPEC-6.1.18-GET-SEMANTICS",
                "KMIPKIT-CLAUSE-SPEC-6.1.18-001",
                "KMIPKIT-REQ-SPEC-6.1.18-001-001",
                1,
                "SHALL",
                "client_to_server",
                [26846, 26849],
                "client",
                "client_1_0",
            ),
            (
                "KMIPKIT-SOURCE-GAP-SPEC-6.1.45-CERTIFICATE-REQUEST-UID-ONLY",
                "KMIPKIT-CLAUSE-SPEC-6.1.45-002",
                "KMIPKIT-REQ-SPEC-6.1.45-002-003",
                2,
                "SHALL",
                "client_to_server",
                [33348, 33353],
                "client",
                "mixed",
            ),
        )
        requirements = {row["requirement_id"]: row for row in catalog["requirements"]}
        clauses = {row["clause_id"]: row for row in catalog["source_clauses"]}
        reviews = {row["source_clause_id"]: row for row in oracle["source_requirement_reviews"]}
        gaps = {row["gap_id"]: row for row in oracle["source_only_requirement_gaps"]}
        crosswalk = {row["requirement_id"]: row for row in oracle["requirement_crosswalk"]}

        for gap_id, clause_id, requirement_id, order, keyword, direction, html_lines, source_actor, clause_scope in expected:
            with self.subTest(requirement_id=requirement_id):
                requirement = requirements[requirement_id]
                clause = clauses[clause_id]
                review = reviews[clause_id]
                gap = gaps[gap_id]
                source_atom = next(
                    atom for atom in review["source_obligations"] if atom["source_order"] == order
                )

                self.assertEqual(requirement["source_clause_ids"], [clause_id])
                self.assertEqual(requirement["source_keyword"], keyword)
                self.assertEqual(requirement["role"], "client")
                self.assertEqual(requirement["direction"], direction)
                self.assertEqual(requirement["scope_state"], "client_1_0")
                self.assertEqual(requirement["status"], "unassigned")
                self.assertEqual(clause["disposition"], "requirement")
                self.assertEqual(clause["scope_state"], clause_scope)
                self.assertIn(requirement_id, clause["requirement_ids"])
                self.assertIn(requirement_id, review["expected_client_requirement_ids"])
                self.assertEqual(source_atom["candidate_requirement_id"], requirement_id)
                self.assertEqual(source_atom["actor"], source_actor)
                self.assertEqual(source_atom["scope_disposition"], "client_1_0")
                self.assertEqual(
                    pinned_source_excerpt("specification/oasis/kmip-2.1/upstream/kmip-spec-v2.1-os.html", html_lines),
                    review["source_excerpt"],
                )
                self.assertEqual(gap["candidate_requirement_id"], requirement_id)
                self.assertIsNone(gap["proposed_requirement_id"])
                self.assertEqual(gap["status"], "source_obligation_covered_by_existing_stable_label")
                self.assertEqual(crosswalk[requirement_id]["source_clause_id"], clause_id)
                self.assertEqual(crosswalk[requirement_id]["source_obligation_order"], order)
                for profile in oracle["profiles"]:
                    self.assertIn(requirement_id, profile["requirement_ids_audited_subset"])

        client_profiles = [row for row in catalog["profiles"] if row["role"] == "client"]
        for profile in client_profiles:
            for _, _, requirement_id, *_ in expected:
                self.assertIn(requirement_id, profile["requirement_ids"])

